    {id:"e255", sec:"listen", type:"E-L7", inst:"이 사람은 왜 병원에 갔습니까?", uz:"Hikoyani tinglang va savolga mos javobni tanlang.", audio:"여자: 저는 어제 아침부터 배가 많이 아팠습니다. 점심도 먹지 못했습니다. 그래서 반장님께 말씀드리고 오후에 병원에 갔습니다. 의사 선생님이 약을 주셨고 오늘은 많이 좋아졌습니다.",
     opts:["배가 아파서", "손을 다쳐서", "건강 검진을 받으려고", "친구를 만나려고"], a:0,
     exp:"<b>배가 아프다</b> — qorin og'rimoq: shuning uchun shifoxonaga borgan."},
    {id:"e256", sec:"listen", type:"E-L7", inst:"이 사람은 한국에서 무엇을 하고 싶습니까?", uz:"Hikoyani tinglang va savolga mos javobni tanlang.", audio:"남자: 저는 다음 달에 한국에 가서 자동차 부품 공장에서 일할 겁니다. 일을 하면서 돈을 모으고 싶습니다. 그리고 한국어를 더 열심히 공부해서 나중에 한국 회사와 무역하는 일을 하고 싶습니다.",
     opts:["한국어를 공부하고 돈을 모으고 싶습니다.", "자동차를 사고 싶습니다.", "대학교에 가고 싶습니다.", "식당을 열고 싶습니다."], a:0,
     exp:"Ishlab <b>pul yig'moqchi</b> va <b>koreys tilini o'rganmoqchi</b>. 무역 — savdo, 부품 — ehtiyot qism."},
    {id:"e257", sec:"listen", type:"E-L7", inst:"이번 주 토요일에 무엇을 합니까?", uz:"Hikoyani tinglang va savolga mos javobni tanlang.", audio:"여자: 다음 주 월요일에 새 기계가 들어옵니다. 그래서 이번 주 토요일에 공장 정리를 하려고 합니다. 토요일에 나오는 사람은 일요일에 쉬고 수당도 받습니다. 참가할 사람은 내일까지 반장님께 말씀해 주십시오.",
     opts:["공장을 정리합니다.", "새 기계를 삽니다.", "회식을 합니다.", "쉽니다."], a:0,
     exp:"Shanba kuni <b>zavodni tartibga keltirish</b>. 정리 — tartibga solish, 참가하다 — qatnashmoq."},
    {id:"e258", sec:"listen", type:"E-L7", inst:"이 사람은 퇴근 후에 무엇을 합니까?", uz:"Hikoyani tinglang va savolga mos javobni tanlang.", audio:"남자: 저는 회사에서 일이 끝나면 기숙사 근처 체육관에서 운동을 합니다. 하루 종일 서서 일해서 다리가 아플 때가 많습니다. 그래서 운동을 하면 몸이 훨씬 좋아집니다. 주말에는 동료들과 축구도 합니다.",
     opts:["체육관에서 운동을 합니다.", "한국어를 공부합니다.", "친구를 만납니다.", "잔업을 합니다."], a:0,
     exp:"Ishdan keyin <b>sport zalida mashq qiladi</b>. 체육관 — sport zali, 하루 종일 — kun bo'yi."},
    {id:"e259", sec:"listen", type:"E-L7", inst:"외국인 등록증을 잃어버리면 어떻게 해야 합니까?", uz:"Hikoyani tinglang va savolga mos javobni tanlang.", audio:"여자: 외국인 등록증은 한국에서 아주 중요한 신분증입니다. 은행이나 병원에 갈 때 꼭 필요합니다. 만약 등록증을 잃어버리면 14일 안에 출입국 사무소에 가서 다시 만들어야 합니다.",
     opts:["14일 안에 출입국 사무소에 가야 합니다.", "은행에 가서 신고해야 합니다.", "회사에 말하면 됩니다.", "새로 만들 필요가 없습니다."], a:0,
     exp:"Yo'qotilsa — <b>14 kun ichida migratsiya idorasiga</b> borib qayta olish kerak. 신분증 — shaxs guvohnomasi. (Qoidalar o'zgarishi mumkin: rasmiy manbadan tekshiring.)"},
    {id:"e260", sec:"listen", type:"E-L7", inst:"이 사람의 고향 집은 어떻습니까?", uz:"Hikoyani tinglang va savolga mos javobni tanlang.", audio:"남자: 제 고향은 사마르칸트입니다. 우리 집은 크지 않지만 마당이 넓습니다. 마당에는 포도나무와 사과나무가 있습니다. 여름이 되면 가족들이 마당에 모여서 같이 저녁을 먹습니다.",
     opts:["마당이 넓습니다.", "집이 아주 큽니다.", "마당이 없습니다.", "아파트입니다."], a:0,
     exp:"Uy katta emas, lekin <b>hovlisi keng</b>. 마당 — hovli, 포도나무 — tok."},
    {id:"e261", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"한국에서는 일할 때 인사가 아주 중요합니다. 아침에 출근하면 먼저 동료들에게 인사를 합니다. 인사를 잘하면 동료들과 쉽게 친해질 수 있습니다.",
     opts:["인사를 잘하는 것이 중요합니다.", "아침에 일찍 출근해야 합니다.", "동료들은 친절합니다.", "한국 사람들은 바쁩니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>salomlashish juda muhim</b>. 인사 — salom, 친해지다 — do'stlashmoq."},
    {id:"e262", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"작업장에서는 항상 안전모와 안전화를 착용해야 합니다. 귀찮다고 착용하지 않으면 큰 사고가 날 수 있습니다.",
     opts:["작업장에서는 보호 장비를 꼭 착용해야 합니다.", "안전화는 비쌉니다.", "작업장은 귀찮은 곳입니다.", "사고는 자주 나지 않습니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>himoya vositalarini doim kiyish</b> shart. 귀찮다 — erinchoqlik, malol kelmoq."},
    {id:"e263", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"돈을 모으려면 계획을 세워서 써야 합니다. 월급을 받으면 먼저 저금할 돈을 정하고 남은 돈으로 생활하는 것이 좋습니다.",
     opts:["계획을 세워서 돈을 써야 합니다.", "월급이 적습니다.", "돈을 많이 써야 합니다.", "은행에 자주 가야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>pulni reja bilan sarflash</b>. 계획을 세우다 — reja tuzmoq, 저금하다 — jamg'armoq."},
    {id:"e264", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"외국어를 배울 때는 그 나라 문화도 같이 배우는 것이 좋습니다. 문화를 알면 말의 뜻을 더 잘 이해할 수 있기 때문입니다.",
     opts:["외국어와 문화를 같이 배우는 것이 좋습니다.", "외국어는 배우기 어렵습니다.", "문화는 중요하지 않습니다.", "여행을 많이 가야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>til bilan birga madaniyatni ham o'rganish</b>. -기 때문입니다 — chunki."},
    {id:"e265", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"몸이 아프면 참지 말고 바로 병원에 가야 합니다. 작은 병도 늦게 치료하면 더 큰 병이 될 수 있습니다.",
     opts:["아프면 바로 병원에 가야 합니다.", "병원은 비쌉니다.", "작은 병은 괜찮습니다.", "약을 많이 먹어야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>kasal bo'lsangiz darhol shifoxonaga boring</b>. 참다 — chidamoq, 치료하다 — davolamoq."},
    {id:"e266", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"같은 방을 쓰는 사람과 잘 지내려면 서로 규칙을 정하는 것이 좋습니다. 청소 순서나 조용히 해야 하는 시간을 미리 정하면 문제가 생기지 않습니다.",
     opts:["함께 사는 사람과 규칙을 정하는 것이 좋습니다.", "혼자 사는 것이 좋습니다.", "청소는 매일 해야 합니다.", "방이 넓어야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>xonadosh bilan qoidalar kelishib olish</b>. 규칙 — qoida, 순서 — navbat."},
    {id:"e267", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"잠을 충분히 자지 않으면 일할 때 실수를 많이 하게 됩니다. 그래서 일하기 전날에는 일찍 자는 것이 좋습니다.",
     opts:["일하기 전에는 충분히 자야 합니다.", "실수를 해도 괜찮습니다.", "밤에 일하는 것이 좋습니다.", "잠을 적게 자야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>ishdan oldin yetarlicha uxlash</b>. 충분히 — yetarlicha, 전날 — oldingi kun."},
    {id:"e268", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"기계에 문제가 생기면 혼자 고치려고 하지 말고 바로 관리자에게 알려야 합니다. 잘 모르고 만지면 다칠 수 있습니다.",
     opts:["기계에 문제가 생기면 관리자에게 알려야 합니다.", "기계는 혼자 고쳐야 합니다.", "관리자는 바쁩니다.", "기계를 자주 만져야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>buzilishni rahbarga xabar qilish</b>. 관리자 — mas'ul shaxs, 만지다 — tegmoq."},
    {id:"e269", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"한국 생활에 빨리 적응하려면 한국 사람들과 많이 이야기하는 것이 좋습니다. 처음에는 실수를 해도 계속 이야기하면 한국어 실력도 늘고 친구도 생깁니다.",
     opts:["한국 사람들과 많이 이야기하는 것이 좋습니다.", "실수를 하면 안 됩니다.", "고향 친구만 만나야 합니다.", "한국어는 책으로만 배워야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>koreyslar bilan ko'p gaplashish</b>. 적응하다 — moslashmoq, 실력이 늘다 — mahorat oshmoq."},
    {id:"e270", sec:"read", type:"E-R8", inst:"다음 글의 중심 생각을 고르십시오.", uz:"Matnning asosiy fikrini tanlang.", text:"물건을 살 때 영수증을 꼭 받아 두는 것이 좋습니다. 영수증이 있으면 물건에 문제가 있을 때 바꾸거나 돈을 돌려받을 수 있습니다.",
     opts:["물건을 사면 영수증을 받아 두는 것이 좋습니다.", "물건을 바꾸면 안 됩니다.", "영수증은 필요 없습니다.", "비싼 물건만 사야 합니다."], a:0,
     exp:"Asosiy fikr odatda birinchi yoki oxirgi gapda: <b>chekni olib qo'yish</b> foydali. 돌려받다 — qaytarib olmoq."},
    {id:"e271", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"많이 다치셨어요?",
     opts:["아니요, 조금 다쳤어요. 괜찮아요.", "네, 많이 먹었어요.", "아니요, 다치세요.", "네, 다쳐 주세요."], a:0,
     exp:"<b>다치다</b> — jarohatlanmoq. Javob: «Yo'q, ozgina, hechqisi yo'q»."},
    {id:"e272", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"제가 도와 드릴까요?",
     opts:["네, 감사합니다. 이것 좀 들어 주세요.", "아니요, 도와줬어요.", "네, 도와요.", "제가 도와 드릴게요."], a:0,
     exp:"Yordam taklifiga: <b>네, 감사합니다</b> + iltimos. -아/어 드릴까요? — «...ib beraymi?»"},
    {id:"e273", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"다음 주에 휴가라서 고향에 다녀올 거예요.",
     opts:["그래요? 잘 다녀오세요.", "어서 오세요.", "처음 뵙겠습니다.", "잘 먹겠습니다."], a:0,
     exp:"Ketib qaytadigan odamga: <b>잘 다녀오세요</b> — yaxshi borib keling. 다녀오다 — borib kelmoq."},
    {id:"e274", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"이 일은 처음이라서 잘 모르겠어요.",
     opts:["걱정하지 마세요. 제가 가르쳐 드릴게요.", "네, 처음 뵙겠습니다.", "잘 모르겠어요.", "일이 끝났어요."], a:0,
     exp:"Yangi ishchiga: <b>걱정하지 마세요</b> — xavotir olmang, o'rgataman."},
    {id:"e275", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"저 시험에 합격했어요!",
     opts:["축하해요! 정말 잘됐네요.", "괜찮아요. 다음에 잘하면 돼요.", "미안해요.", "실례합니다."], a:0,
     exp:"<b>합격하다</b> — imtihondan o'tmoq → <b>축하해요</b>. 괜찮아요… — yiqilganda aytiladi."},
    {id:"e276", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"오늘 정말 수고 많으셨습니다.",
     opts:["네, 수고하셨습니다.", "네, 잘 먹겠습니다.", "아니요, 처음이에요.", "축하합니다."], a:0,
     exp:"Ish oxirida: <b>수고하셨습니다</b> — «charchamang, rahmat» deb javob qaytariladi."},
    {id:"e277", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"여기에서 사진을 찍어도 돼요?",
     opts:["아니요, 여기에서는 안 돼요.", "네, 사진이에요.", "아니요, 사진기가 있어요.", "네, 찍었어요."], a:0,
     exp:"<b>-아/어도 돼요?</b> — ruxsat so'rash. Taqiq: <b>안 돼요</b>."},
    {id:"e278", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"죄송하지만 좀 천천히 말씀해 주시겠어요?",
     opts:["네, 다시 천천히 말할게요.", "네, 빨리 말할게요.", "아니요, 말하지 마세요.", "천천히 드세요."], a:0,
     exp:"Sekinroq gapirish so'raldi → <b>천천히 말할게요</b>. Bu iborani ishda tez-tez ishlating!"},
    {id:"e279", sec:"listen", type:"E-L3", inst:"다음을 듣고 이어지는 말로 알맞은 것을 고르십시오.", uz:"Tinglang va keyin aytiladigan gapni tanlang.", audio:"저녁에 같이 삼겹살 먹으러 갈래요?",
     opts:["좋아요. 몇 시에 만날까요?", "네, 삼겹살이에요.", "아니요, 삼겹살이 아니에요.", "잘 먹었습니다."], a:0,
     exp:"Taklif <b>-(으)ㄹ래요?</b> → rozilik va vaqt so'rash: 좋아요. 몇 시에 만날까요?"},
    {id:"e280", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"아플 때 의사를 만나서 치료를 받는 곳입니다.",
     opts:["병원", "약국", "은행", "학교"], a:0,
     exp:"Shifokor davolaydigan joy — <b>병원</b>. Dori sotiladigan joy — 약국."},
    {id:"e281", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"비행기를 타고 내리는 곳입니다.",
     opts:["공항", "기차역", "항구", "정류장"], a:0,
     exp:"<b>공항</b> — aeroport. 항구 — port, 정류장 — avtobus bekati."},
    {id:"e282", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"돈을 내고 물건을 산 후에 받는 종이입니다.",
     opts:["영수증", "통장", "여권", "편지"], a:0,
     exp:"<b>영수증</b> — chek, kvitansiya."},
    {id:"e283", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"더울 때 방을 시원하게 해 주는 기계입니다.",
     opts:["에어컨", "냉장고", "세탁기", "난로"], a:0,
     exp:"Xonani salqin qiladi — <b>에어컨</b>. 난로 — isitgich (zid)."},
    {id:"e284", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"회사에서 한 달 동안 일하고 받는 돈입니다.",
     opts:["월급", "용돈", "세금", "요금"], a:0,
     exp:"<b>월급</b> — oylik maosh. 용돈 — cho'ntak puli, 세금 — soliq, 요금 — to'lov."},
    {id:"e285", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"다른 나라 돈을 한국 돈으로 바꾸는 것입니다.",
     opts:["환전", "저금", "송금", "계산"], a:0,
     exp:"<b>환전</b> — valyuta almashtirish. 송금 — pul o'tkazmasi, 저금 — jamg'arma."},
    {id:"e286", sec:"read", type:"E-R5", inst:"다음 설명에 맞는 것을 고르십시오.", uz:"Tavsifga mos keladiganini tanlang.", text:"높은 곳에 올라갈 때 밟고 올라가는 물건입니다.",
     opts:["사다리", "망치", "장갑", "가위"], a:0,
     exp:"Balandga chiqish uchun — <b>사다리</b> (narvon). 밟다 — bosmoq."},
    {id:"e287", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"저는 매일 아침 6시에 일어나서 기숙사 식당에서 아침을 먹습니다. 그리고 7시 30분에 회사 버스를 타고 출근합니다.",
     opts:["저는 회사 버스를 타고 출근합니다.", "저는 아침을 먹지 않습니다.", "저는 7시에 일어납니다.", "저는 걸어서 출근합니다."], a:0,
     exp:"Ishga <b>kompaniya avtobusida</b> boradi. Soat 6 da turadi, yotoqxonada nonushta qiladi."},
    {id:"e288", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"우리 공장은 일주일에 5일 일하고 토요일과 일요일에는 쉽니다. 하지만 일이 많을 때는 토요일에도 일합니다.",
     opts:["일이 많으면 토요일에도 일합니다.", "공장은 일요일에도 일합니다.", "공장은 매일 쉽니다.", "토요일에는 항상 일합니다."], a:0,
     exp:"<b>일이 많을 때는</b> — ish ko'p bo'lganda shanba ham ishlanadi. Odatda haftasiga 5 kun."},
    {id:"e289", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"제 동료 아지즈 씨는 한국어를 아주 잘합니다. 그래서 새로 온 외국인 근로자들을 많이 도와줍니다.",
     opts:["아지즈 씨는 새 근로자들을 도와줍니다.", "아지즈 씨는 한국어를 못합니다.", "아지즈 씨는 새로 온 근로자입니다.", "아지즈 씨는 도움을 받습니다."], a:0,
     exp:"Aziz koreys tilini yaxshi biladi va <b>yangi ishchilarga yordam beradi</b>."},
    {id:"e290", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"이번 달 월급날인 25일이 일요일이라서 월급이 하루 전인 24일에 나옵니다.",
     opts:["이번 달 월급은 24일에 받습니다.", "이번 달 월급은 26일에 받습니다.", "월급날은 매달 24일입니다.", "이번 달에는 월급이 없습니다."], a:0,
     exp:"25-sana yakshanba, shuning uchun bu oy maosh <b>bir kun oldin — 24-sanada</b>."},
    {id:"e291", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"저는 주말에 외국인 근로자 센터에서 한국어를 배웁니다. 수업료는 없고 선생님들도 아주 친절합니다.",
     opts:["한국어 수업은 무료입니다.", "수업료가 비쌉니다.", "저는 평일에 공부합니다.", "선생님들은 불친절합니다."], a:0,
     exp:"<b>수업료는 없고</b> — dars puli yo'q, ya'ni <b>bepul</b> (무료)."},
    {id:"e292", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"회사 식당은 점심시간에만 문을 엽니다. 아침과 저녁은 기숙사에서 직접 만들어 먹어야 합니다.",
     opts:["저녁은 기숙사에서 만들어 먹습니다.", "회사 식당은 저녁에도 문을 엽니다.", "아침은 회사 식당에서 먹습니다.", "기숙사에서는 요리할 수 없습니다."], a:0,
     exp:"Oshxona faqat tushlikda ochiq; nonushta va kechki ovqat <b>yotoqxonada o'zlari pishiradi</b>."},
    {id:"e293", sec:"read", type:"E-R7", inst:"다음 글의 내용과 같은 것을 고르십시오.", uz:"Matn mazmuniga mos keladiganini tanlang.", text:"어제 공장에 새 기계가 들어왔습니다. 그래서 오늘 오전에는 기계 사용법을 배웠습니다.",
     opts:["오늘 오전에 기계 사용법을 배웠습니다.", "새 기계는 다음 주에 들어옵니다.", "기계 사용법은 오후에 배웁니다.", "기계가 고장 났습니다."], a:0,
     exp:"<b>사용법</b> — foydalanish usuli: bugun ertalab o'rganildi. Mashina kecha keldi."},
    {id:"e294", sec:"read", type:"E-R6", inst:"다음 글을 읽고 질문에 답하십시오.", uz:"Matnni o'qing va savolga javob bering.", text:"[분실물 안내]\n어제 회사 식당에서 검은색 지갑을 찾았습니다. 지갑을 잃어버린 분은 1층 사무실로 오십시오.\n\n질문: 지갑을 찾으려면 어디로 가야 합니까?",
     opts:["1층 사무실", "회사 식당", "기숙사", "경찰서"], a:0,
     exp:"<b>분실물</b> — yo'qolgan buyum. Hamyon <b>1-qavatdagi ofisda</b>."},
    {id:"e295", sec:"read", type:"E-R6", inst:"다음 글을 읽고 질문에 답하십시오.", uz:"Matnni o'qing va savolga javob bering.", text:"[기숙사 안내]\n이번 주 금요일 오후 2시부터 4시까지 물이 나오지 않습니다. 필요한 물은 미리 받아 두십시오.\n\n질문: 금요일 오후에 무엇을 할 수 없습니까?",
     opts:["물을 쓸 수 없습니다.", "전기를 쓸 수 없습니다.", "밖에 나갈 수 없습니다.", "식당에 갈 수 없습니다."], a:0,
     exp:"<b>물이 나오지 않습니다</b> — suv kelmaydi. 미리 받아 두다 — oldindan to'ldirib qo'ymoq."},
    {id:"e296", sec:"read", type:"E-R6", inst:"다음 글을 읽고 질문에 답하십시오.", uz:"Matnni o'qing va savolga javob bering.", text:"[건강 교실]\n일시: 매주 수요일 저녁 7시\n장소: 외국인 근로자 센터 3층\n내용: 허리 운동, 스트레칭\n※ 운동복을 입고 오세요.\n\n질문: 건강 교실에 갈 때 무엇을 입어야 합니까?",
     opts:["운동복", "작업복", "정장", "한복"], a:0,
     exp:"※ belgisi — eslatma: <b>운동복</b> (sport kiyimi). 작업복 — ish kiyimi, 정장 — kostyum."},
    {id:"e297", sec:"read", type:"E-R6", inst:"다음 글을 읽고 질문에 답하십시오.", uz:"Matnni o'qing va savolga javob bering.", text:"[회식 안내]\n이번 주 목요일 저녁 7시에 회사 근처 '행복식당'에서 회식을 합니다. 참석하지 못하는 사람은 수요일까지 반장님께 말씀해 주십시오.\n\n질문: 회식에 못 가는 사람은 어떻게 해야 합니까?",
     opts:["수요일까지 반장님께 말해야 합니다.", "목요일에 식당에 전화해야 합니다.", "돈을 내야 합니다.", "아무것도 안 해도 됩니다."], a:0,
     exp:"<b>참석하다</b> — qatnashmoq. Bora olmasangiz — <b>chorshanbagacha brigadirga</b> ayting."},
    {id:"e298", sec:"read", type:"E-R6", inst:"다음 글을 읽고 질문에 답하십시오.", uz:"Matnni o'qing va savolga javob bering.", text:"[주차 안내]\n다음 주 월요일부터 회사 주차장 공사를 합니다. 공사 기간에는 회사 뒤 공터에 차를 세우십시오.\n\n질문: 다음 주에 차를 어디에 세워야 합니까?",
     opts:["회사 뒤 공터", "회사 주차장", "기숙사 앞", "길가"], a:0,
     exp:"<b>공사</b> — ta'mirlash ishlari, <b>공터</b> — bo'sh maydon. 차를 세우다 — mashinani qo'ymoq."},
    {id:"e299", sec:"read", type:"E-R6", inst:"다음 글을 읽고 질문에 답하십시오.", uz:"Matnni o'qing va savolga javob bering.", text:"[택배 보관 안내]\n택배는 경비실에서 보관합니다. 경비실은 밤 10시에 문을 닫으니까 그 전에 찾아가십시오.\n\n질문: 택배는 언제까지 찾아가야 합니까?",
     opts:["밤 10시 전", "아침 10시 전", "오후 1시 전", "밤 12시 전"], a:0,
     exp:"<b>경비실</b> — qorovulxona, <b>택배</b> — posilka. Kechki 10 dan oldin olish kerak."},
    {id:"e300", sec:"read", type:"E-R4", inst:"다음 대화의 (    )에 들어갈 가장 알맞은 것을 고르십시오.", uz:"Dialogdagi qavs ichiga eng mos javobni tanlang.", text:"가: 이 근처에 약국이 있어요?\n나: (    )",
     opts:["네, 은행 옆에 있어요.", "네, 약을 먹었어요.", "아니요, 아파요.", "약국에서 일해요."], a:0,
     exp:"<b>있어요?</b> — joy so'ralyapti: javobda manzil — <b>은행 옆</b>."},
    {id:"e301", sec:"read", type:"E-R4", inst:"다음 대화의 (    )에 들어갈 가장 알맞은 것을 고르십시오.", uz:"Dialogdagi qavs ichiga eng mos javobni tanlang.", text:"가: 무엇을 드시겠어요?\n나: (    )",
     opts:["비빔밥 하나 주세요.", "네, 먹었어요.", "아니요, 배불러요.", "식당에 가요."], a:0,
     exp:"<b>무엇을 드시겠어요?</b> — Nima yeysiz? Buyurtma: <b>비빔밥 하나 주세요</b>."},
    {id:"e302", sec:"read", type:"E-R4", inst:"다음 대화의 (    )에 들어갈 가장 알맞은 것을 고르십시오.", uz:"Dialogdagi qavs ichiga eng mos javobni tanlang.", text:"가: 내일 몇 시까지 출근해야 돼요?\n나: (    )",
     opts:["8시까지 오세요.", "공장으로 오세요.", "버스를 타고 오세요.", "친구하고 오세요."], a:0,
     exp:"<b>몇 시까지</b> — soat nechagacha? Javobda vaqt."},
    {id:"e303", sec:"read", type:"E-R4", inst:"다음 대화의 (    )에 들어갈 가장 알맞은 것을 고르십시오.", uz:"Dialogdagi qavs ichiga eng mos javobni tanlang.", text:"가: 주말에 보통 뭐 해요?\n나: (    )",
     opts:["친구들하고 축구를 해요.", "주말이에요.", "토요일에 왔어요.", "네, 주말이 좋아요."], a:0,
     exp:"<b>뭐 해요?</b> — nima qilasiz? Javobda harakat: futbol o'ynayman."},
    {id:"e304", sec:"read", type:"E-R4", inst:"다음 대화의 (    )에 들어갈 가장 알맞은 것을 고르십시오.", uz:"Dialogdagi qavs ichiga eng mos javobni tanlang.", text:"가: 이 서류를 누구에게 드릴까요?\n나: (    )",
     opts:["사무실의 김 과장님께 드리세요.", "서류가 많아요.", "내일 드릴게요.", "책상 위에 있어요."], a:0,
     exp:"<b>누구에게</b> — kimga? Javobda odam: 김 과장님께. <b>께</b> — 에게 ning hurmat shakli."},
    {id:"e305", sec:"listen", type:"E-L5", inst:"다음을 듣고 들은 내용과 같은 것을 고르십시오.", uz:"Tinglang va eshitganingizga mos gapni tanlang.", audio:"남자: 나디라 씨, 내일 아침에 회의가 있어요. 8시까지 회의실로 오세요.\n여자: 네, 알겠습니다.",
     opts:["내일 아침에 회의가 있습니다.", "회의는 오후에 합니다.", "여자는 회의에 가지 않습니다.", "회의는 식당에서 합니다."], a:0,
     exp:"<b>회의실</b> — majlislar zali; majlis ertaga ertalab soat 8 da."},
    {id:"e306", sec:"listen", type:"E-L5", inst:"다음을 듣고 들은 내용과 같은 것을 고르십시오.", uz:"Tinglang va eshitganingizga mos gapni tanlang.", audio:"여자: 지난주에 산 이 신발이 너무 작아요. 큰 걸로 바꿀 수 있어요?\n남자: 네, 영수증 있으시면 바꿔 드릴게요.",
     opts:["여자는 신발을 바꾸고 싶어 합니다.", "신발이 너무 큽니다.", "여자는 오늘 신발을 샀습니다.", "영수증이 없어도 바꿀 수 있습니다."], a:0,
     exp:"Poyabzal kichik — <b>kattasiga almashtirmoqchi</b>. Chek kerak."},
    {id:"e307", sec:"listen", type:"E-L5", inst:"다음을 듣고 들은 내용과 같은 것을 고르십시오.", uz:"Tinglang va eshitganingizga mos gapni tanlang.", audio:"남자: 이번 겨울에 고향에 가요?\n여자: 아니요, 비행기표가 너무 비싸서 봄에 가려고 해요.",
     opts:["여자는 봄에 고향에 갈 겁니다.", "여자는 겨울에 고향에 갑니다.", "비행기표가 쌉니다.", "남자는 고향에 갑니다."], a:0,
     exp:"Chipta qimmat, shuning uchun <b>bahorda</b> boradi. -(으)려고 하다 — niyat."},
    {id:"e308", sec:"listen", type:"E-L5", inst:"다음을 듣고 들은 내용과 같은 것을 고르십시오.", uz:"Tinglang va eshitganingizga mos gapni tanlang.", audio:"여자: 기계에서 이상한 냄새가 나요.\n남자: 그래요? 그럼 기계를 끄고 바로 반장님께 알립시다.",
     opts:["두 사람은 기계를 끌 겁니다.", "기계에서 소리가 납니다.", "남자는 기계를 고칩니다.", "여자는 반장님입니다."], a:0,
     exp:"<b>냄새가 나다</b> — hid chiqmoq. <b>-(으)ㅂ시다</b> — «...aylik»: mashinani o'chirib, xabar beramiz."},
    {id:"e309", sec:"read", type:"E-R2", inst:"다음 표지판은 무슨 뜻입니까? 알맞은 것을 고르십시오.", uz:"Bu belgi nimani anglatadi? Mosini tanlang.", sign:"음식물 반입 금지",
     opts:["음식을 가지고 들어가면 안 됩니다.", "음식을 사 오십시오.", "음식을 버리십시오.", "여기에서 음식을 파십시오."], a:0,
     exp:"<b>반입</b> — olib kirish, <b>금지</b> — taqiq: ovqat olib kirish mumkin emas."},
    {id:"e310", sec:"read", type:"E-R2", inst:"다음 표지판은 무슨 뜻입니까? 알맞은 것을 고르십시오.", uz:"Bu belgi nimani anglatadi? Mosini tanlang.", sign:"고온 주의",
     opts:["뜨거우니까 조심하십시오.", "추우니까 옷을 입으십시오.", "물을 마시십시오.", "창문을 여십시오."], a:0,
     exp:"<b>고온</b> — yuqori harorat: «Issiq, ehtiyot bo'ling». 뜨겁다 — qaynoq."},
    {id:"e311", sec:"read", type:"E-R2", inst:"다음 표지판은 무슨 뜻입니까? 알맞은 것을 고르십시오.", uz:"Bu belgi nimani anglatadi? Mosini tanlang.", sign:"지게차 주의",
     opts:["지게차가 다니니까 조심하십시오.", "지게차를 타십시오.", "지게차를 고치십시오.", "지게차를 사십시오."], a:0,
     exp:"<b>지게차</b> — yuklagich. Bu yerda yuklagich yuradi — ehtiyot bo'ling."},
    {id:"e312", sec:"read", type:"E-R2", inst:"다음 표지판은 무슨 뜻입니까? 알맞은 것을 고르십시오.", uz:"Bu belgi nimani anglatadi? Mosini tanlang.", sign:"사용 중",
     opts:["지금 다른 사람이 쓰고 있습니다.", "지금 비어 있습니다.", "고장 났습니다.", "청소를 하고 있습니다."], a:0,
     exp:"<b>사용 중</b> — «Band» (hozir foydalanilmoqda). 비어 있다 — bo'sh."}
